import { escapeHTML as e } from '../core.js';
import { notice, options, table } from '../ui.js';
export function caseReferences(c, s) {
    const index = Math.max(0, c.pages.findIndex(p => p.id === s.currentPageId)), p = c.pages[index];
    return `<div class="case-reference"><div class="case-eyebrow"><span class="eyebrow">REFERENCE DOSSIER</span><span class="chip">${index + 1} / ${c.pages.length}</span></div><h2>${e(c.title)}</h2><label class="sr-only" for="case-page">Reference page</label><select id="case-page" aria-label="Case reference page">${options(c.pages.map(p => p.id), p.id, Object.fromEntries(c.pages.map(p => [p.id, p.title])))}</select><article id="case-exhibit" tabindex="-1"><h3>${e(p.title)}</h3>${p.body.split('\n\n').map(s => `<p>${e(s)}</p>`).join('')}${p.table ? table(p.table.rows, p.table.columns) : ''}</article><nav class="case-pager" aria-label="Reference page navigation"><button class="secondary" data-page="${c.pages[index - 1]?.id ?? ''}" ${index === 0 ? 'disabled' : ''}>Previous page</button><button class="secondary" data-page="${c.pages[index + 1]?.id ?? ''}" ${index === c.pages.length - 1 ? 'disabled' : ''}>Next page</button></nav><p class="muted">Exhibit navigation does not change your current task or answer.</p>${s.caseVersion !== c.version ? notice('Case version changed', 'Your existing answers and checkpoints are retained; review the current references before continuing.') : ''}</div>`;
}
export function caseTaskBar(c, s, q) {
    const i = c.tasks.findIndex(t => t.id === s.currentTaskId);
    return `<div class="case-task-controls"><span class="chip">CASE TASK ${i + 1} / ${c.tasks.length}</span><select id="case-task" aria-label="Case task">${options(c.tasks.map(t => t.id), s.currentTaskId, Object.fromEntries(c.tasks.map((t, i) => [t.id, `${i + 1}. ${t.title}`])))}</select><button class="text-button" data-case-action="standalone">Open standalone</button></div><details class="case-task-prompt" open><summary>${e(q.title)}</summary><p>${e(q.task)}</p><div class="case-task-links"><button class="text-button" data-case-action="copy">Start from my standalone attempt</button>${c.tasks[i].pageRefs?.map(id => `<button class="text-button" data-page="${e(id)}">Exhibit: ${e(c.pages.find(p => p.id === id)?.title ?? id)}</button>`).join('') ?? ''}</div></details>`;
}
